static C225: Cell = std::sync::OnceLock::new();
const B225: &[Beat] = &[
    Beat::new("Yield is the share of dies on a wafer that work", BEAT_MS)
        .note("A 300 mm wafer is printed with a grid of identical chips (dies), then each is probed electrically before it is cut out. Yield is good dies divided by all dies. A mature process on a small chip can pass well over 90%; a new node or a huge chip can start far lower.", "Yield is the share of dies on a wafer that work")
        .detail("yield", &["YIELD"]),

    Beat::new("Random defects land on the wafer during hundreds of steps", BEAT_MS)
        .note("Particles, scratches, pattern flaws and contamination hit the wafer at some rate per square centimetre, called defect density (D0). Over hundreds of process steps a few dozen killer defects per wafer is normal. Where they land is close to random.", "Random defects land on the wafer during hundreds of steps")
        .detail("yield", &["YIELD"]),

    Beat::new("At wafer sort, any die with a killer defect fails", BEAT_MS)
        .note("A probe card touches every die's pads and runs tests. One killer defect anywhere in a die usually scraps it, or forces it to be sold as a cut-down part with blocks disabled. The failing dies are inked out in the wafer map and never packaged. Here the small-die wafer passes 379 of 392 (97%).", "At wafer sort, any die with a killer defect fails")
        .detail("yield", &["YIELD"]),

    Beat::new("The same defects kill far more big dies", BEAT_MS)
        .note("Yield falls roughly exponentially with die area times defect density. The same defects that cost a few small dies wipe out a large share of big ones: here only 55 of 68 big dies survive (81%). That is why reticle-size AI chips are expensive and why makers split designs into chiplets.", "The same defects kill far more big dies")
        .detail("yield", &["YIELD"]),

    Beat::new("Wafer cost divided by good dies is the real cost per chip", BEAT_MS)
        .note("A leading-edge wafer costs around $20k or more whether its dies work or not. Fewer dies per wafer and lower yield multiply together, so a big die can cost many times more per good unit than its area alone suggests. Yield gains drop straight into gross margin.", "Wafer cost divided by good dies is the real cost per chip")
        .detail("yield", &["YIELD"]),

    Beat::new("Inspection finds the defect sources and yield climbs as a node matures", BEAT_MS)
        .note("Fabs scan wafers with optical and e-beam inspection tools, trace defects back to the step and tool that caused them, and fix them. Cut the defects to a third and the big-die yield here rises to 93%. That learning curve is why new nodes ramp slowly. Related: Taiwan Semiconductor (TSM), Intel (INTC), KLA (KLAC), NVIDIA (NVDA).", "Inspection finds the defect sources and yield climbs as a node matures")
        .detail("yield", &["YIELD"]),

];
fn b225() -> Box<dyn Scene> {
    Box::new(Page { cell: &C225, glb: include_bytes!("../../../tools/pbr3d/assets/term_TRM_YIELD.glb"), beats: B225, zooms: &[] })
}

static C226: Cell = std::sync::OnceLock::new();
const B226: &[Beat] = &[
    Beat::new("Every request goes through a policy check", BEAT_MS)
        .note("Zero trust is a security model that drops the idea of a trusted internal network and checks identity, device health and policy on every request. Access is granted per application and per session with least privilege, instead of through a flat network connection. The model became standard after remote work and cloud apps removed the network perimeter, and it drives spending on identity, endpoint and access products. Related: Zscaler (ZS), Palo Alto Networks (PANW), CrowdStrike (CRWD), Okta (OKTA).", "Every request goes through a policy check")
        .detail("zero trust", &["ZERO TRUST"]),

    Beat::new("Least privilege per app, not the network", BEAT_MS)
        .note("Zero trust is a security model that drops the idea of a trusted internal network and checks identity, device health and policy on every request. Access is granted per application and per session with least privilege, instead of through a flat network connection. The model became standard after remote work and cloud apps removed the network perimeter, and it drives spending on identity, endpoint and access products. Related: Zscaler (ZS), Palo Alto Networks (PANW), CrowdStrike (CRWD), Okta (OKTA).", "Least privilege per app, not the network")
        .detail("zero trust", &["ZERO TRUST"]),

];
