static C227: Cell = std::sync::OnceLock::new();
const B227: &[Beat] = &[
    Beat::new("The old way: one box per feature, wired point to point", BEAT_MS)
        .note("A conventional car has 70 to 150 electronic control units (ECUs), one for the windows, one for the seats, one for the brakes and so on, each wired to its own sensors and to the others. The harness that ties them together can run to several kilometres of copper and weigh 50 kg or more, and it is one of the costliest parts to build.", "The old way: one box per feature, wired point to point")
        .detail("zonal architecture", &["ZONAL ARCHITECTURE"]),

    Beat::new("Zonal: a few zone controllers by location, one central brain", BEAT_MS)
        .note("A zonal architecture groups everything by where it sits in the car. A zone controller in each corner powers and talks to the sensors, lights and motors near it, and a central high-performance computer runs the actual features as software. Dozens of ECUs collapse into a handful of boxes.", "Zonal: a few zone controllers by location, one central brain")
        .detail("zonal architecture", &["ZONAL ARCHITECTURE"]),

    Beat::new("Sensors talk to the nearest zone; Ethernet carries it to the centre", BEAT_MS)
        .note("Each sensor or actuator now needs only a short wire to its zone. The zones join the central computer over a few automotive Ethernet links (1 to 10 Gbit/s) instead of hundreds of dedicated wires, and the same backbone can carry camera data for driver assistance.", "Sensors talk to the nearest zone; Ethernet carries it to the centre")
        .detail("zonal architecture", &["ZONAL ARCHITECTURE"]),

    Beat::new("Software updates reach the whole car over the air", BEAT_MS)
        .note("With the logic in one central computer, a carmaker can ship a new feature or a fix over the cellular link and push it to every zone, the way phones update. That is the core of the 'software-defined vehicle' carmakers are moving to.", "Software updates reach the whole car over the air")
        .detail("zonal architecture", &["ZONAL ARCHITECTURE"]),

    Beat::new("Less copper, more central chips", BEAT_MS)
        .note("Fewer, shorter wires cut harness weight and assembly cost substantially. The shift moves silicon spend from many cheap microcontrollers to a few high-performance SoCs, zone MCUs and Ethernet switches. Related: NXP (NXPI), Infineon (IFNNY), Renesas (6723.T), Marvell (MRVL) for automotive Ethernet.", "Less copper, more central chips")
        .detail("zonal architecture", &["ZONAL ARCHITECTURE"]),

];
